// Parse the JSON results and extract key data
const fileContent = $input.first().json.data;
const results = JSON.parse(fileContent);

const macro = results.macro || {};
const portfolio = results.portfolio || [];

// Verdict counts
const counts = { Buy: 0, Hold: 0, Pass: 0, Avoid: 0 };
for (const stock of portfolio) {
  if (counts.hasOwnProperty(stock.verdict)) {
    counts[stock.verdict]++;
  }
}

// Top 3 by score
const sorted = [...portfolio].sort((a, b) => b.score - a.score);
const top3 = sorted.slice(0, 3).map(s => ({
  ticker: s.ticker,
  company: s.company,
  score: s.score,
  verdict: s.verdict,
  price: s.price,
  one_year_target: s.one_year_target,
  upside_pct: s.upside_pct
}));

// Stocks with earnings within 7 days
const earningsAlerts = portfolio.filter(s => {
  return s.earnings_countdown_days !== null &&
         s.earnings_countdown_days >= 0 &&
         s.earnings_countdown_days <= 7;
}).map(s => ({
  ticker: s.ticker,
  company: s.company,
  next_earnings: s.next_earnings,
  countdown_days: s.earnings_countdown_days,
  verdict: s.verdict
}));

// Full portfolio summary sorted by score
const summaryTable = sorted.map(s => ({
  ticker: s.ticker,
  company: s.company,
  verdict: s.verdict,
  score: s.score,
  price: s.price,
  one_year_target: s.one_year_target,
  upside_pct: s.upside_pct,
  earnings_countdown_days: s.earnings_countdown_days,
  sector: s.sector
}));

// Pass through raw portfolio for Notion
return [{
  json: {
    generated_at: results.generated_at,
    macro: {
      overall_signal: macro.overall_signal,
      overall_score: macro.overall_score,
      recession_probability: macro.recession_probability
    },
    counts: counts,
    top3: top3,
    earningsAlerts: earningsAlerts,
    summaryTable: summaryTable,
    totalStocks: portfolio.length,
    rawPortfolio: portfolio
  }
}];

const data = $input.first().json;
const d = data.generated_at ? data.generated_at.split('T')[0] : new Date().toISOString().split('T')[0];

// Verdict emoji mapping
const vEmoji = { Buy: '\u2705', Hold: '\u26A0\uFE0F', Pass: '\u23F8\uFE0F', Avoid: '\u274C' };

// --- Build HTML email ---
let html = '';
html += '<div style="font-family: Arial, sans-serif; max-width: 700px; margin: 0 auto;">';

// Header
html += '<div style="background: #1a237e; color: white; padding: 20px; border-radius: 8px 8px 0 0; text-align: center;">';
html += '<h1 style="margin: 0; font-size: 22px;">Portfolio Analyzer Daily Report</h1>';
html += `<p style="margin: 5px 0 0; opacity: 0.8;">${d}</p>`;
html += '</div>';

// Macro
const macro = data.macro;
const macroColor = macro.overall_signal === 'Risk On' ? '#2e7d32' : macro.overall_signal === 'Cautious' ? '#f57f17' : '#c62828';
html += `<div style="background: ${macroColor}; color: white; padding: 12px 20px; font-size: 14px;">`;
html += `<strong>Macro:</strong> ${macro.overall_signal} (${macro.overall_score}/10) &nbsp;|&nbsp; `;
html += `<strong>Recession Risk:</strong> ${macro.recession_probability}`;
html += '</div>';

// Verdict counts bar
const c = data.counts;
html += '<div style="display: flex; padding: 15px 20px; background: #f5f5f5; gap: 15px; font-size: 14px;">';
html += `<span style="color: #2e7d32;"><strong>${c.Buy}</strong> Buy</span>`;
html += `<span style="color: #f57f17;"><strong>${c.Hold}</strong> Hold</span>`;
html += `<span style="color: #757575;"><strong>${c.Pass}</strong> Pass</span>`;
html += `<span style="color: #c62828;"><strong>${c.Avoid}</strong> Avoid</span>`;
html += `<span style="margin-left: auto; color: #999;">${data.totalStocks} stocks analyzed</span>`;
html += '</div>';

// Top 3 Picks
html += '<div style="padding: 20px;">';
html += '<h2 style="color: #1a237e; font-size: 16px; margin: 0 0 10px;">Top 3 Picks</h2>';
html += '<table style="width: 100%; border-collapse: collapse; font-size: 13px;">';
html += '<tr style="background: #e8eaf6;"><th style="padding: 8px; text-align: left;">Ticker</th><th>Score</th><th>Verdict</th><th style="text-align: right;">Price</th><th style="text-align: right;">Target</th><th style="text-align: right;">Upside</th></tr>';
for (const s of data.top3) {
  const upsideColor = s.upside_pct > 0 ? '#2e7d32' : '#c62828';
  const upsideStr = s.upside_pct != null ? (s.upside_pct > 0 ? '+' : '') + s.upside_pct.toFixed(1) + '%' : 'N/A';
  html += '<tr style="border-bottom: 1px solid #eee;">';
  html += `<td style="padding: 8px;"><strong>${s.ticker}</strong></td>`;
  html += `<td style="text-align: center;">${s.score}/10</td>`;
  html += `<td style="text-align: center;">${vEmoji[s.verdict] || ''} ${s.verdict}</td>`;
  html += `<td style="text-align: right;">$${s.price ? s.price.toFixed(2) : 'N/A'}</td>`;
  html += `<td style="text-align: right;">$${s.one_year_target ? s.one_year_target.toFixed(2) : 'N/A'}</td>`;
  html += `<td style="text-align: right; color: ${upsideColor};">${upsideStr}</td>`;
  html += '</tr>';
}
html += '</table></div>';

// Earnings Alerts
if (data.earningsAlerts && data.earningsAlerts.length > 0) {
  html += '<div style="padding: 10px 20px; background: #fff3e0; border-left: 4px solid #ff9800;">';
  html += '<h3 style="margin: 0 0 8px; font-size: 14px; color: #e65100;">\u23F0 Earnings Alerts (within 7 days)</h3>';
  for (const a of data.earningsAlerts) {
    const urgent = a.countdown_days <= 2 ? ' <strong style="color: red;">IMMINENT</strong>' : '';
    html += `<p style="margin: 4px 0; font-size: 13px;">${a.ticker} (${a.company}) - <strong>${a.countdown_days} day(s)</strong> [${a.next_earnings}]${urgent}</p>`;
  }
  html += '</div>';
}

// Full Portfolio Table
html += '<div style="padding: 20px;">';
html += '<h2 style="color: #1a237e; font-size: 16px; margin: 0 0 10px;">Full Portfolio</h2>';
html += '<table style="width: 100%; border-collapse: collapse; font-size: 12px;">';
html += '<tr style="background: #e8eaf6;"><th style="padding: 6px; text-align: left;">Ticker</th><th>Score</th><th>Verdict</th><th style="text-align: right;">Price</th><th style="text-align: right;">Target</th><th style="text-align: right;">Upside</th><th>Earnings</th></tr>';
for (const s of data.summaryTable) {
  const upsideColor = s.upside_pct > 0 ? '#2e7d32' : '#c62828';
  const upsideStr = s.upside_pct != null ? (s.upside_pct > 0 ? '+' : '') + s.upside_pct.toFixed(1) + '%' : 'N/A';
  const earn = s.earnings_countdown_days != null ? s.earnings_countdown_days + 'd' : '-';
  html += '<tr style="border-bottom: 1px solid #eee;">';
  html += `<td style="padding: 6px;"><strong>${s.ticker}</strong></td>`;
  html += `<td style="text-align: center;">${s.score}/10</td>`;
  html += `<td style="text-align: center;">${vEmoji[s.verdict] || ''} ${s.verdict}</td>`;
  html += `<td style="text-align: right;">$${s.price ? s.price.toFixed(2) : 'N/A'}</td>`;
  html += `<td style="text-align: right;">$${s.one_year_target ? s.one_year_target.toFixed(2) : 'N/A'}</td>`;
  html += `<td style="text-align: right; color: ${upsideColor};">${upsideStr}</td>`;
  html += `<td style="text-align: center;">${earn}</td>`;
  html += '</tr>';
}
html += '</table></div>';

// Footer
html += '<div style="padding: 15px 20px; background: #f5f5f5; border-radius: 0 0 8px 8px; font-size: 11px; color: #999; text-align: center;">';
html += 'Generated by Ultimate Stock Portfolio Analyzer. Not financial advice.';
html += '</div></div>';

// Plain text fallback
let plain = `Portfolio Report - ${d}\n`;
plain += `Macro: ${macro.overall_signal} (${macro.overall_score}/10) | Recession Risk: ${macro.recession_probability}\n\n`;
plain += `Verdicts: ${c.Buy} Buy | ${c.Hold} Hold | ${c.Pass} Pass | ${c.Avoid} Avoid\n\n`;
plain += 'Top Picks:\n';
for (const s of data.top3) {
  plain += `  ${s.ticker} - ${s.verdict} (${s.score}/10) - $${s.price ? s.price.toFixed(2) : 'N/A'} -> $${s.one_year_target ? s.one_year_target.toFixed(2) : 'N/A'}\n`;
}

return [{ json: { html: html, plain: plain, subject: `Portfolio Report ${d} | ${c.Buy} Buy, ${c.Hold} Hold, ${c.Pass} Pass, ${c.Avoid} Avoid`, ...data } }];

// Push each stock to Notion database via API
const data = $input.first().json;
const portfolio = data.rawPortfolio || [];
const apiKey = $env.NOTION_API_KEY;
const dbId = $env.NOTION_DATABASE_ID;

if (!apiKey || !dbId) {
  return [{ json: { status: 'skipped', reason: 'NOTION_API_KEY or NOTION_DATABASE_ID not set' } }];
}

const headers = {
  'Authorization': `Bearer ${apiKey}`,
  'Notion-Version': '2022-06-28',
  'Content-Type': 'application/json'
};

const results = [];

for (const stock of portfolio) {
  // Check if stock already exists
  const queryResp = await fetch(`https://api.notion.com/v1/databases/${dbId}/query`, {
    method: 'POST',
    headers: headers,
    body: JSON.stringify({
      filter: { property: 'Ticker', title: { equals: stock.ticker } }
    })
  });
  const queryData = await queryResp.json();
  const existingPage = queryData.results && queryData.results.length > 0 ? queryData.results[0].id : null;

  // Build properties
  const props = {
    'Ticker': { title: [{ text: { content: stock.ticker } }] },
    'Company': { rich_text: [{ text: { content: stock.company || '' } }] },
    'Verdict': { select: { name: stock.verdict } },
    'Score': { number: stock.score },
    'Price': { number: stock.price ? Math.round(stock.price * 100) / 100 : null },
    '1Y Target': { number: stock.one_year_target ? Math.round(stock.one_year_target * 100) / 100 : null },
    'Sector': stock.sector ? { select: { name: stock.sector } } : { select: null },
    'Last Updated': { date: { start: new Date().toISOString().split('T')[0] } }
  };

  if (stock.upside_pct != null) {
    props['Upside %'] = { number: Math.round(stock.upside_pct / 100 * 10000) / 10000 };
  }
  if (stock.next_earnings) {
    props['Earnings Date'] = { date: { start: stock.next_earnings } };
  }
  if (stock.earnings_countdown_days != null) {
    props['Earnings Countdown'] = { number: stock.earnings_countdown_days };
  }
  if (stock.component_scores) {
    props['Valuation Score'] = { number: stock.component_scores.valuation };
    props['Quality Score'] = { number: stock.component_scores.quality };
    props['Momentum Score'] = { number: stock.component_scores.momentum };
    props['Agent Consensus'] = { number: stock.component_scores.agent_consensus };
  }
  if (stock.bull_case && stock.bull_case.length > 0) {
    props['Bull Case'] = { rich_text: [{ text: { content: stock.bull_case.slice(0, 3).join(' | ').substring(0, 2000) } }] };
  }
  if (stock.bear_case && stock.bear_case.length > 0) {
    props['Bear Case'] = { rich_text: [{ text: { content: stock.bear_case.slice(0, 3).join(' | ').substring(0, 2000) } }] };
  }

  // Find top bull/bear agents
  if (stock.agent_verdicts && stock.agent_verdicts.length > 0) {
    const bull = stock.agent_verdicts.reduce((a, b) => a.score > b.score ? a : b);
    const bear = stock.agent_verdicts.reduce((a, b) => a.score < b.score ? a : b);
    props['Top Bull Agent'] = { rich_text: [{ text: { content: `${bull.agent} (${bull.score}/10)` } }] };
    props['Top Bear Agent'] = { rich_text: [{ text: { content: `${bear.agent} (${bear.score}/10)` } }] };
  }

  if (existingPage) {
    // Update existing row
    await fetch(`https://api.notion.com/v1/pages/${existingPage}`, {
      method: 'PATCH',
      headers: headers,
      body: JSON.stringify({ properties: props })
    });
    results.push({ ticker: stock.ticker, action: 'updated' });
  } else {
    // Create new row
    await fetch('https://api.notion.com/v1/pages', {
      method: 'POST',
      headers: headers,
      body: JSON.stringify({ parent: { database_id: dbId }, properties: props })
    });
    results.push({ ticker: stock.ticker, action: 'created' });
  }
}

return [{ json: { status: 'success', stocks_updated: results.length, details: results } }];

// Error handler: captures failure from the analyzer script
const errorItem = $input.first();
const errorMsg = errorItem.json.stderr || errorItem.json.error || 'Unknown error';
const exitCode = errorItem.json.exitCode || 'N/A';
const now = new Date().toISOString().split('T')[0];

const html = `<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">`
  + `<div style="background: #c62828; color: white; padding: 20px; border-radius: 8px 8px 0 0; text-align: center;">`
  + `<h2 style="margin: 0;">Portfolio Analyzer FAILED</h2>`
  + `<p style="margin: 5px 0 0; opacity: 0.8;">${now}</p></div>`
  + `<div style="padding: 20px; background: #fff;">`
  + `<p><strong>Exit Code:</strong> ${exitCode}</p>`
  + `<pre style="background: #f5f5f5; padding: 15px; border-radius: 4px; overflow-x: auto; font-size: 12px;">${errorMsg}</pre>`
  + `<h3>Checklist:</h3><ul>`
  + `<li>Python environment and dependencies (yfinance, rich)</li>`
  + `<li>Network connectivity to Yahoo Finance</li>`
  + `<li>Disk space for /tmp/portfolio_results.json</li>`
  + `<li>Script path: /home/user/qlib</li>`
  + `</ul></div></div>`;

return [{ json: { html: html, subject: `[ERROR] Portfolio Analyzer Failed - ${now}` } }];
